import ipaddress
import json

from framework_evidence import run_tool


SCOPE = ipaddress.ip_network("192.168.5.0/24")
CANDIDATES = ["192.168.5.3"]  # Reported responsive by the supplied host-discovery evidence.


def main():
    results = []
    for candidate in CANDIDATES:
        address = ipaddress.ip_address(candidate)
        if address not in SCOPE:
            results.append({"target": candidate, "status": "not_scanned", "error": "candidate is outside the task-provided scope"})
            continue

        argv = [
            "nmap", "-sU", "-sV", "--version-light", "-n", "-Pn", "--reason",
            "--top-ports", "1000", "-oX", "-", str(address)
        ]
        try:
            results.append(run_tool(argv))
        except Exception as exc:
            results.append({
                "command": argv,
                "status": "error",
                "error": f"run_tool raised {type(exc).__name__}: {exc}"
            })

    print(json.dumps({"evidence_version": 1, "scope": str(SCOPE), "coverage": "Nmap top 1000 UDP ports per in-scope responsive candidate", "tool_runs": results}, sort_keys=True))


if __name__ == "__main__":
    main()

