import json
import re

from framework_evidence import run_tool


def strings(value):
    if isinstance(value, str):
        yield value
    elif isinstance(value, dict):
        for item in value.values():
            yield from strings(item)
    elif isinstance(value, (list, tuple)):
        for item in value:
            yield from strings(item)


def emit(label, result):
    print(json.dumps({"stage": label, "result": result}, ensure_ascii=False, default=str))


search_argv = [
    "msfconsole", "-q", "-x",
    "search type:exploit ssh; search OpenSSH; search type:auxiliary ssh_version; exit -y",
]
try:
    search_result = run_tool(search_argv)
    emit("catalog_search", search_result)
except Exception as exc:
    emit("catalog_search_error", {"command": search_argv, "error": str(exc)})
    raise SystemExit(0)

# Extract module paths from the actual console output, rather than assuming a
# particular Metasploit release's search result set.
paths = set()
for text in strings(search_result):
    for match in re.finditer(r"(?<![A-Za-z0-9_])(?:exploit|auxiliary)/[A-Za-z0-9_./-]+", text):
        path = match.group(0).rstrip(".,;:)")
        if ".." not in path.split("/"):
            paths.add(path)

# Include exploit candidates returned by the SSH/OpenSSH searches and any
# SSH-scanner results; inspect metadata only, never invoke run/check/exploit.
selected = {
    path for path in paths
    if path.startswith("exploit/") or path.startswith("auxiliary/scanner/ssh/")
}
selected.add("auxiliary/scanner/ssh/ssh_version")

if not selected:
    emit("module_review_status", {
        "status": "incomplete",
        "reason": "The search output yielded no module paths to inspect; consult the retained search envelope.",
    })
else:
    info_command = "; ".join("info " + path for path in sorted(selected)) + "; exit -y"
    info_argv = ["msfconsole", "-q", "-x", info_command]
    try:
        info_result = run_tool(info_argv)
        emit("module_information", info_result)
        emit("review_scope", {
            "modules_requested_for_info": sorted(selected),
            "target_facts_for_comparison": [
                "Observed service: OpenSSH 8.2p1 Ubuntu 4ubuntu0.13 on in-scope host 192.168.5.3.",
                "Credentialed survey evidence confirms SSH access as uid 1000 (student); the supplied preview is partial, so unshown survey facts are unknown.",
            ],
            "actions_not_performed": ["exploit execution", "module check", "authentication attempt"],
        })
    except Exception as exc:
        emit("module_information_error", {
            "command": info_argv,
            "modules_requested_for_info": sorted(selected),
            "error": str(exc),
            "status": "incomplete",
        })

