import errno
import json
import os
import pty
import re
import select
import signal
import sys
import time

HOST = "192.168.5.3"
USER = "student"
PASSWORD = "password"
TIMEOUT_SECONDS = 240
MAX_TRANSCRIPT_BYTES = 2_000_000

# Each check is sent as its own line in the authenticated interactive shell.
CHECKS = [
    ("identity", "id"),
    ("groups", "groups"),
    ("system", "uname -a"),
    ("sudo", "sudo -n -l"),
    ("suid_files", "find / -xdev -type f -perm -4000 -printf '%m %u:%g %p\\n'"),
    ("sgid_files", "find / -xdev -type f -perm -2000 -printf '%m %u:%g %p\\n'"),
    ("file_capabilities", "getcap -r /"),
    ("cron_directories", "ls -la /etc/cron.d /etc/cron.daily /etc/cron.hourly /etc/cron.weekly /etc/cron.monthly /var/spool/cron/crontabs"),
    ("system_crontab", "cat /etc/crontab"),
    ("user_crontab", "crontab -l"),
    ("software_versions", "dpkg-query -W -f='${binary:Package}\\t${Version}\\n'"),
    ("listening_services", "ss -lntup"),
    ("processes", "ps -eo user,pid,comm,args"),
]


def main():
    result = {
        "target": HOST,
        "user": USER,
        "authentication": "not_established",
        "checks": [],
        "ssh_exit_status": None,
        "timed_out": False,
        "transcript_truncated": False,
        "transcript": "",
        "errors": [],
        "coverage_limitations": [],
    }
    argv = [
        "ssh", "-tt",
        "-o", "ConnectTimeout=10",
        "-o", "StrictHostKeyChecking=accept-new",
        "-o", "PreferredAuthentications=password",
        "-o", "PubkeyAuthentication=no",
        USER + "@" + HOST,
    ]
    transcript = bytearray()
    sent_password = False
    sent_checks = False
    command_batch = "".join(
        command + "\n"
        + "printf '__CHECK_" + str(i) + "_" + name + "__\\n'\n"
        for i, (name, command) in enumerate(CHECKS, 1)
    )
    started = time.monotonic()
    child_pid = None

    try:
        child_pid, master_fd = pty.fork()
        if child_pid == 0:
            env = os.environ.copy()
            env["TERM"] = "dumb"
            os.execvpe(argv[0], argv, env)

        os.set_blocking(master_fd, False)
        child_status = None
        while time.monotonic() - started < TIMEOUT_SECONDS:
            try:
                ready, _, _ = select.select([master_fd], [], [], 0.2)
            except InterruptedError:
                continue
            if ready:
                try:
                    chunk = os.read(master_fd, 65536)
                except OSError as exc:
                    if exc.errno in (errno.EIO, errno.EBADF):
                        chunk = b""
                    else:
                        raise
                if chunk:
                    if len(transcript) < MAX_TRANSCRIPT_BYTES:
                        remaining = MAX_TRANSCRIPT_BYTES - len(transcript)
                        transcript.extend(chunk[:remaining])
                        if len(chunk) > remaining:
                            result["transcript_truncated"] = True
                    else:
                        result["transcript_truncated"] = True

                    current = bytes(transcript).lower()
                    if not sent_password and re.search(rb"password:\s*$", current):
                        os.write(master_fd, PASSWORD.encode("utf-8") + b"\n")
                        sent_password = True
                        result["authentication"] = "password_submitted_waiting_for_result"
                    if sent_password and not sent_checks and time.monotonic() - started > 1.5:
                        os.write(master_fd, command_batch.encode("utf-8"))
                        sent_checks = True
                    if sent_checks and b"__CHECK_13_processes__" in bytes(transcript):
                        try:
                            os.write(master_fd, b"exit\n")
                        except OSError:
                            pass
                else:
                    break

            if child_status is None:
                waited, status = os.waitpid(child_pid, os.WNOHANG)
                if waited:
                    child_status = status
                    break

        else:
            result["timed_out"] = True
            result["coverage_limitations"].append(
                "SSH interaction exceeded the 240-second execution timeout; remaining checks may not have run."
            )

        if child_status is None and child_pid is not None:
            try:
                waited, status = os.waitpid(child_pid, os.WNOHANG)
                if waited:
                    child_status = status
                else:
                    os.kill(child_pid, signal.SIGTERM)
                    try:
                        _, child_status = os.waitpid(child_pid, 0)
                    except ChildProcessError:
                        pass
            except ChildProcessError:
                pass

        if child_status is not None and os.WIFEXITED(child_status):
            result["ssh_exit_status"] = os.WEXITSTATUS(child_status)
        elif child_status is not None and os.WIFSIGNALED(child_status):
            result["ssh_exit_status"] = "signal:" + str(os.WTERMSIG(child_status))

    except FileNotFoundError as exc:
        result["errors"].append("Local OpenSSH executable unavailable: " + str(exc))
    except Exception as exc:
        result["errors"].append(type(exc).__name__ + ": " + str(exc))
    finally:
        if child_pid:
            try:
                os.kill(child_pid, signal.SIGTERM)
            except OSError:
                pass

    # Do not expose the supplied password if it appeared in terminal echo or output.
    raw = bytes(transcript).replace(PASSWORD.encode("utf-8"), b"[REDACTED_PASSWORD]")
    text = raw.decode("utf-8", errors="replace")
    result["transcript"] = text
    if b"__CHECK_1_identity__" in raw:
        result["authentication"] = "succeeded_shell_marker_observed"
    elif b"Permission denied" in raw or b"Permission denied" in text.encode("utf-8", errors="ignore"):
        result["authentication"] = "server_rejected_authentication"
    elif not sent_password and not result["errors"]:
        result["authentication"] = "password_prompt_not_observed"
        result["coverage_limitations"].append(
            "No SSH password prompt was observed; authentication was not established."
        )
    elif sent_password and result["authentication"] != "succeeded_shell_marker_observed":
        result["authentication"] = "indeterminate_after_password_submission"
        result["coverage_limitations"].append(
            "Password was submitted, but the first host-context marker was not observed; do not infer successful login."
        )

    for i, (name, _command) in enumerate(CHECKS, 1):
        marker = "__CHECK_" + str(i) + "_" + name + "__"
        result["checks"].append({
            "name": name,
            "completion_marker_observed": marker in text,
        })
    if result["transcript_truncated"]:
        result["coverage_limitations"].append(
            "Captured terminal transcript exceeded the 2,000,000-byte recording limit; later output may be absent."
        )
    if not sent_checks:
        result["coverage_limitations"].append(
            "The context-check command batch was not sent because password authentication did not reach the interactive stage."
        )
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

