import framework_evidence


def main():
    review_context = {
        "target": "192.168.5.3",
        "facts_from_authenticated_review": {
            "identity": "student account access was observed",
            "os": "Ubuntu 20.04.6",
            "openssh_server_package": "1:8.2p1-4ubuntu0.13",
            "sudo_package": "1.8.31-1ubuntu1",
            "suid_finding": "/usr/bin/at, mode 6755",
        },
        "limitations": [
            "The sudo package version is recorded as observed; this review does not establish patch status or exploitability.",
            "OpenSSH identification alone does not establish a relevant vulnerable configuration.",
            "The SUID at binary is a host finding, not by itself evidence of a matching Metasploit module.",
            "A local-module check may require a Metasploit session; no exploit is run by this review.",
        ],
        "candidate_hypothesis": "exploit/linux/local/sudo_baron_samedit (CVE-2021-3156), to be validated against module metadata and the target-specific check result",
    }
    print(json.dumps({"review_context": review_context}, sort_keys=True))

    argv = [
        "msfconsole",
        "-q",
        "-x",
        "search cve:2021-3156; info exploit/linux/local/sudo_baron_samedit; use exploit/linux/local/sudo_baron_samedit; check; exit",
    ]
    try:
        result = framework_evidence.run_tool(argv)
        if isinstance(result, str):
            print(result)
        else:
            print(json.dumps(result, sort_keys=True, default=str))
    except Exception as exc:
        print(json.dumps({
            "tool": "msfconsole",
            "argv": argv,
            "execution_error": str(exc),
            "assessment": "No module applicability result was obtained; the error is not a negative vulnerability finding.",
        }, sort_keys=True))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

